WITH matched_keys AS (SELECT id, customer_id FROM sessions INTERSECT SELECT id, customer_id FROM sessions WHERE device = 'mobile'), kept_rows AS (SELECT s.* FROM sessions s INNER JOIN matched_keys k ON s.id = k.id AND s.customer_id = k.customer_id) SELECT browser, customer_id, COUNT(*) FILTER (WHERE country = 'US') AS us_rows, COUNT(*) FILTER (WHERE device = 'desktop') AS desktop_rows, MIN(started_at) AS started_at, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, MAX(started_at) AS last_started_at, COUNT(*) AS row_count FROM kept_rows GROUP BY 1, 2 HAVING row_count >= 1 ORDER BY span_minutes
